class SawAgent < Formula
  desc "SAW remote agent - pairs a machine with a SAW cloud workspace"
  homepage "https://github.com/LenderCom/saw-agent"
  version "0.1.1"

  # Source moved off this tap's own releases to LenderCom/saw-agent-releases as of 0.1.2 — these
  # four url/sha256 pairs are generated by script/bump-formula.rb from that release's minisign-signed
  # manifest.json, by .github/workflows/bump-formula.yml. Do not hand-edit them: that workflow polls
  # saw-agent-releases hourly and opens the bump PR itself, so a stable cut reaches this formula
  # without anyone running the script.
  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/LenderCom/saw-agent-releases/releases/download/v0.1.1/saw-agent_v0.1.1_darwin_arm64.tar.gz"
      sha256 "393e99240d31e5e832dc6ff2b25d0ba71d7ca660467f56958a1efd657f25fc64"
    else
      url "https://github.com/LenderCom/saw-agent-releases/releases/download/v0.1.1/saw-agent_v0.1.1_darwin_amd64.tar.gz"
      sha256 "0e62840af5fa69bdba99c1572a561a8356f8f8931d41bf650e1091e5434f2a46"
    end
  end

  on_linux do
    if Hardware::CPU.arm?
      url "https://github.com/LenderCom/saw-agent-releases/releases/download/v0.1.1/saw-agent_v0.1.1_linux_arm64.tar.gz"
      sha256 "c6c5baeac5022737841c9c3ca635e91be4ce516540b90fe6548ed7cf79900216"
    else
      url "https://github.com/LenderCom/saw-agent-releases/releases/download/v0.1.1/saw-agent_v0.1.1_linux_amd64.tar.gz"
      sha256 "2b8694723b02369417a559301c59ec744ece0a536b3bc5b5433cc7428a7cf3af"
    end
  end

  def install
    # The keg carries the real, versioned binary; it is never the thing on PATH. `bin/saw-agent`
    # is a small dispatch shim (see #shim_script) that prefers a self-updated
    # ~/.saw/bin/saw-agent when present, so `brew upgrade` always refreshes a trusted fallback
    # without fighting an agent that has since taken over its own updates (plan §2.6).
    libexec.install "saw-agent"
    (bin/"saw-agent").write shim_script
    chmod 0755, bin/"saw-agent"
  end

  def shim_script
    <<~SH
      #!/bin/bash
      # Generated by Formula/saw-agent.rb — do not edit directly.
      managed="$HOME/.saw/bin/saw-agent"
      keg="#{opt_libexec}/saw-agent"

      # An executable managed-path file is not proof it RUNS: a truncated, wrong-arch, or
      # otherwise corrupt binary is still `-x` but ENOEXEC on exec, and bash's `exec` on an
      # ENOEXEC file falls back to reinterpreting it as a shell script (or kills the shell) —
      # it does NOT fall through to the next line. So probe it first with a fast, side-effect-free
      # flag: `-version` prints and exits immediately, unlike a bare invocation which would boot
      # the daemon. Only exec the managed copy once the probe proves it actually runs.
      if [ -x "$managed" ] && "$managed" -version >/dev/null 2>&1; then
        exec "$managed" "$@"
      fi

      exec "$keg" "$@"
    SH
  end

  def caveats
    <<~EOS
      Next: pair this machine with a SAW cloud workspace
      ===================================================

      1. Easiest — in the browser, open your SAW workspace, go to Agents, and click
         "Add remote agent". The wizard mints a one-time pair code and hands you the
         exact command below, already filled in — copy, paste, done.

      2. Direct — a workspace operator mints a code (`saw machines pair-code`, or the
         same wizard) and gives it to you:

           SAW_CLOUD_ORG=<org-id> \\
             SAW_CLOUD_PAIR_CODE=<code> \\
             saw-agent --cloud

      3. Self-pair your OWN signed-in machine — no code needed:

           SAW_CLOUD_SELF_PAIR=1 SAW_CLOUD_ORG=<org-id> saw-agent --cloud

         (needs SAW_CLOUD_USER_TOKEN — a signed-in user session bearer)

      NOTE: there is no production SAW cloud yet — agents/accounts/realtime/workspace
      under sawrun.com do not resolve. This formula cannot pair against production
      until those exist, and the stable build ships no compiled-in origins, so a cloud
      attach here needs your own origins set explicitly:

        SAW_CLOUD_AGENTS_URL=... SAW_CLOUD_ACCOUNTS_URL=...
        SAW_CLOUD_REALTIME_URL=... SAW_CLOUD_WORKSPACE_URL=...

      For the dev/internal cloud, install `saw-agent-dev` instead
      (`brew install lendercom/tap/saw-agent-dev`) — it tracks the latest dev-channel
      build and has the dev origins compiled in, so it needs none of the above.

      Once paired, `saw-agent --cloud` IS the long-lived agent process — it stays in the
      foreground; Ctrl-C (or closing the terminal) stops it, and re-running the same
      command brings it back. This formula does not install a launchd/systemd unit — the
      `curl -fsSL https://get.sawrun.com/agent | sh` installer does, if you want the agent
      to survive reboots without a formula-managed service.


      How this installs
      ==================

      saw-agent installs as a keg-fallback + shim pair, not a single binary:
        - #{opt_bin}/saw-agent is a dispatch shim.
        - #{opt_libexec}/saw-agent is this keg's pinned, versioned binary.

      The shim always prefers a healthy ~/.saw/bin/saw-agent (verified with a fast `-version`
      probe, not just executable-bit) over the keg fallback. Nothing here bootstraps that
      managed copy automatically — once the daemon service is running, tell it to adopt
      self-updates itself:

        saw-agent self-update

      The RUNNING service binary is what installs itself into ~/.saw/bin/saw-agent; the shim
      then picks up that self-updating copy on its next start. `brew upgrade` never touches
      ~/.saw/bin — it only refreshes the keg fallback, so a broken self-update still has a
      working, signed binary underneath it.
    EOS
  end

  test do
    assert_match "saw-agent #{version}", shell_output("#{bin}/saw-agent --version")
  end
end
